1	import { SignJWT, jwtVerify } from "jose";
2	import { cookies } from "next/headers";
3	import { cache } from "react";
4	import { db } from "./db";
5	import { getSettingInt } from "./settings";
6	import type { User } from "@prisma/client";
7	
8	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
9	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
10	
11	export async function createSession(userId: string) {
12	  // Session lifetime is admin-configurable (`session_length_days`, default 30).
13	  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
14	  const days = Math.max(1, await getSettingInt("session_length_days", 30));
15	  const token = await new SignJWT({ sub: userId })
16	    .setProtectedHeader({ alg: "HS256" })
17	    .setIssuedAt()
18	    .setExpirationTime(`${days}d`)
19	    .sign(secret);
20	  const jar = await cookies();
21	  jar.set(COOKIE, token, {
22	    httpOnly: true,
23	    sameSite: "lax",
24	    secure: process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1",
25	    maxAge: 60 * 60 * 24 * days,
26	    path: "/",
27	  });
28	}
29	
30	export async function destroySession() {
31	  const jar = await cookies();
32	  jar.delete(COOKIE);
33	}
34	
35	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
36	
37	/** The real signed-in account, ignoring any impersonation. */
38	export const realUser = cache(async (): Promise<User | null> => {
39	  const jar = await cookies();
40	  const token = jar.get(COOKIE)?.value;
41	  if (!token) return null;
42	  try {
43	    const { payload } = await jwtVerify(token, secret);
44	    if (!payload.sub) return null;
45	    const user = await db.user.findUnique({ where: { id: payload.sub } });
46	    if (!user || user.suspended) return null;
47	    return user;
48	  } catch {
49	    return null;
50	  }
51	});
52	
53	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
54	export const currentUser = cache(async (): Promise<User | null> => {
55	  const real = await realUser();
56	  if (!real) return null;
57	  if (real.role === "ADMIN") {
58	    const jar = await cookies();
59	    const imp = jar.get(IMP_COOKIE)?.value;
60	    if (imp) {
61	      try {
62	        const { payload } = await jwtVerify(imp, secret);
63	        if (payload.adminId === real.id && typeof payload.sub === "string") {
64	          const target = await db.user.findUnique({ where: { id: payload.sub } });
65	          if (target) return target;
66	        }
67	      } catch {
68	        /* expired/invalid impersonation — fall through to real user */
69	      }
70	    }
71	  }
72	  return real;
73	});
74	
75	/** Non-null when the current request is an admin impersonating a customer. */
76	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
77	  const real = await realUser();
78	  if (!real || real.role !== "ADMIN") return null;
79	  const target = await currentUser();
80	  if (!target || target.id === real.id) return null;
81	  return { admin: real, target };
82	});
83	
84	export async function setImpersonation(targetUserId: string) {
85	  const real = await realUser();
86	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
87	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id })
88	    .setProtectedHeader({ alg: "HS256" })
89	    .setIssuedAt()
90	    .setExpirationTime("2h")
91	    .sign(secret);
92	  const jar = await cookies();
93	  jar.set(IMP_COOKIE, token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 7200 });
94	}
95	
96	export async function clearImpersonation() {
97	  const jar = await cookies();
98	  jar.delete(IMP_COOKIE);
99	}
100	
101	export async function requireUser(): Promise<User> {
102	  const user = await currentUser();
103	  if (!user) throw new Error("UNAUTHORIZED");
104	  return user;
105	}
106	
107	export async function requireAdmin(): Promise<User> {
108	  const user = await requireUser();
109	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
110	  return user;
111	}
112	
113	/**
114	 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
115	 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
116	 * per-area gating lives in lib/rbac.ts (`requireArea`).
117	 */
118	export async function requireStaff(): Promise<User> {
119	  const user = await realUser();
120	  if (!user) throw new Error("UNAUTHORIZED");
121	  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
122	    throw new Error("FORBIDDEN");
123	  }
124	  return user;
125	}
