24	/** Cookie the register page sets when a visitor arrives via a referral link. */
25	const REF_COOKIE = "nxeon_ref";
26	/** Cookie the billing CouponField sets when a promo code is applied. */
27	const COUPON_COOKIE = "nxeon_coupon";
28	
29	/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
30	async function uniqueReferralCode(): Promise<string> {
31	  for (let i = 0; i < 6; i++) {
32	    const code = generateReferralCode();
33	    const clash = await db.user.findUnique({ where: { referralCode: code } });
34	    if (!clash) return code;
35	  }
36	  // Extremely unlikely; fall back to a longer code.
37	  return generateReferralCode(12);
38	}
