40	async function audit(userId: string | null, action: string, detail?: string) {
41	  await db.auditLog.create({ data: { userId, action, detail } });
42	}
43	
44	/** Local sentinel: renewNow's compare-and-swap lost the race (already renewed). */
45	class AlreadyRenewedError extends Error {
46	  constructor() {
47	    super("ALREADY_RENEWED");
48	    this.name = "AlreadyRenewedError";
49	  }
50	}
