52	// ---------- Auth ----------
53	
54	const credsSchema = z.object({
55	  email: z.string().email().max(200),
56	  password: z.string().min(8).max(200),
57	});
58	
59	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
60	  const parsed = credsSchema
61	    .extend({
62	      name: z.string().min(1).max(100),
63	      password: z
64	        .string()
65	        .min(8, "Password must be at least 8 characters")
66	        .max(200)
67	        .regex(/[a-zA-Z]/, "Password must include a letter")
68	        .regex(/[0-9]/, "Password must include a number"),
69	    })
70	    .safeParse({
71	    email: formData.get("email"),
72	    password: formData.get("password"),
73	    name: formData.get("name"),
74	  });
75	  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
76	  const { email, password, name } = parsed.data;
77	
78	  const existing = await db.user.findUnique({ where: { email } });
79	  if (existing) return { error: "An account with that email already exists." };
80	
81	  // Capture a referral from the `ref` cookie (set by the register page) if the
82	  // code maps to a real user. Self-referral is impossible here (new account).
83	  const jar = await cookies();
84	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
85	  let referredById: string | null = null;
86	  if (refCode) {
87	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
88	    if (referrer) referredById = referrer.id;
89	  }
90	
91	  const referralCode = await uniqueReferralCode();
92	  const user = await db.user.create({
93	    data: {
94	      email,
95	      name,
96	      passwordHash: await bcrypt.hash(password, 12),
97	      referralCode,
98	      referredById,
99	    },
100	  });
101	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
102	  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
103	  try {
104	    await grantSignupCredit(user.id);
105	  } catch { /* non-fatal */ }
106	  jar.delete(REF_COOKIE);
107	  try {
108	    const { sendMail, emails } = await import("./mailer");
109	    const tpl = emails.welcome(name);
110	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
111	  } catch { /* email is best-effort */ }
112	  await createSession(user.id);
113	  redirect("/dashboard");
114	}
115	
116	export async function login(
117	  prev: any,
118	  formData: FormData,
119	): Promise<{ error?: string; needs2fa?: boolean }> {
120	  const parsed = credsSchema.safeParse({
121	    email: formData.get("email"),
122	    password: formData.get("password"),
123	  });
124	  if (!parsed.success) return { error: "Invalid email or password." };
125	
126	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
127	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
128	  const hdrs = await headers();
129	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
130	  const rlId = `${parsed.data.email}:${ip}`;
131	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
132	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
133	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
134	
135	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
136	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
137	    return { error: "Invalid email or password." };
138	  }
139	  if (user.suspended) return { error: "This account is suspended." };
140	
141	  // Two-factor challenge, if enabled on the account.
142	  if (user.totpEnabled) {
143	    const code = String(formData.get("code") ?? "").trim();
144	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
145	    if (!(await verifyTotpForUser(user.id, code))) {
146	      return { error: "Invalid 2FA code.", needs2fa: true };
147	    }
148	  }
149	
150	  resetRateLimit(`login:${rlId}`);
151	  await audit(user.id, "user.login");
152	  await createSession(user.id);
153	  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
154	}
155	
156	export async function logout() {
157	  await destroySession();
158	  redirect("/login");
159	}
