161	// ---------- Ordering ----------
162	
163	const orderSchema = z.object({
164	  planId: z.string().min(1),
165	  osTemplateId: z.string().min(1),
166	  hostname: z
167	    .string()
168	    .min(3)
169	    .max(40)
170	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
171	});
172	
173	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
174	async function scheduleNode(planRamMB: number) {
175	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
176	  if (nodes.length === 0) return null;
177	  const loads = await Promise.all(
178	    nodes.map(async (n) => {
179	      const agg = await db.server.findMany({
180	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
181	        select: { plan: { select: { ramMB: true } } },
182	      });
183	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
184	      return { node: n, free: n.capacityRamMB - used };
185	    })
186	  );
187	  loads.sort((a, b) => b.free - a.free);
188	  const best = loads[0];
189	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
190	  return best.node;
191	}
192	
193	/**
194	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
195	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
196	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
197	 */
198	async function serverLimitError(userId: string): Promise<string | null> {
199	  const cap = await getSettingInt("max_servers_per_user", 10);
200	  if (cap <= 0) return null; // 0 (or negative) = unlimited
201	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
202	  if (owned >= cap) {
203	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
204	  }
205	  return null;
206	}
207	
208	export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
209	  const user = await requireUser();
210	  // Refuse new orders once the user is at their server cap.
211	  const limitErr = await serverLimitError(user.id);
212	  if (limitErr) return { error: limitErr };
213	  const parsed = orderSchema.safeParse({
214	    planId: formData.get("planId"),
215	    osTemplateId: formData.get("osTemplateId"),
216	    hostname: formData.get("hostname"),
217	  });
218	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
219	
220	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
221	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
222	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
223	
224	  // Image requirements (control panels/apps need more resources)
225	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
226	    return {
227	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
228	    };
229	  }
230	
231	  const cap = await capacityCheck(plan.id);
232	  if (!cap.ok) return { error: cap.reason };
233	
234	  // Optional: node (location) selection, else auto-schedule
235	  const requestedNodeId = String(formData.get("nodeId") ?? "");
236	  let nodeId: string | null = null;
237	  if (requestedNodeId) {
238	    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
239	    if (!n) return { error: "Selected location is not available." };
240	    nodeId = n.id;
241	  } else {
242	    const n = await scheduleNode(plan.ramMB);
243	    nodeId = n?.id ?? null;
244	  }
245	
246	  // Add-ons (booleans)
247	  const addons = {
248	    malwareScanner: formData.get("addon_malware") === "1",
249	    dailyBackup: formData.get("addon_backup") === "1",
250	    docker: formData.get("addon_docker") === "1",
251	  };
252	
253	  // Optional SSH key added at deploy time
254	  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
255	  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);
256	
257	  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
258	  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
259	  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
260	  const ipCents = wantsDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
261	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
262	  // Mirrors lib/order.ts orderQuote so every VPS charge path agrees. Renewals in
263	  // worker/billing.ts bill the regular vpsTermPriceCents (untouched), so the
264	  // strikethrough shown on marketing pages is the real renewal price and this
265	  // discounted value is the real first-term price — displayed === charged.
266	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
267	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
268	  const promo = currentPromo(new Date());
269	  const chargeCents = promoPriceCents(regularPlanCents, promo) + ipCents;
270	  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";
271	
272	  const isAdmin = user.role === "ADMIN";
273	  const freeRequested = formData.get("free") === "1" && isAdmin;
274	
275	  if (!freeRequested && user.balanceCents < chargeCents) {
276	    return { error: "Insufficient balance. Top up your wallet first." };
277	  }
278	
279	  let server;
280	  try {
281	    server = await db.$transaction(async (tx) => {
282	    if (!freeRequested) {
283	      await debitWallet(tx, user.id, chargeCents);
284	      await tx.walletTransaction.create({
285	        data: {
286	          userId: user.id,
287	          amountCents: -chargeCents,
288	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
289	        },
290	      });
291	      // PAID invoice for the initial order (one distinct charge per order — the
292	      // new server row is created below, so there is no replay to dedupe).
293	      await tx.invoice.create({
294	        data: invoiceCreateData({
295	          userId: user.id,
296	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
297	          status: "PAID",
298	          period: { start: new Date(), end: addMonths(new Date(), term.months) },
299	          lineItems: [
300	            { description: `${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
301	          ],
302	        }),
303	      });
304	    }
305	    if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
306	      const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
307	      if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
308	    }
309	    const s = await tx.server.create({
310	      data: {
311	        name: parsed.data.hostname,
312	        hostname: parsed.data.hostname,
313	        userId: user.id,
314	        planId: plan.id,
315	        osTemplateId: os.id,
316	        nodeId,
317	        addons,
318	        termMonths: term.months,
319	        wantsDedicatedIp,
320	        isFree: freeRequested,
321	        expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
322	      },
323	    });
324	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
325	    return s;
326	    });
327	  } catch (e) {
328	    if (e instanceof InsufficientBalanceError) {
329	      return { error: "Insufficient balance. Top up your wallet first." };
330	    }
331	    throw e;
332	  }
333	
334	  await audit(user.id, "server.order", `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`);
335	  // A first paid order can unlock a referral reward (free admin grants don't count).
336	  if (!freeRequested) {
337	    try {
338	      await maybeRewardReferral(user.id);
339	    } catch { /* non-fatal */ }
340	  }
341	  redirect(`/dashboard/servers/${server.id}`);
342	}
343	
344	/**
345	 * Deploy flow that does NOT require pre-funding the wallet. If the wallet covers
346	 * the order (or it's a free admin grant) it provisions immediately; otherwise it
347	 * returns a Stripe Checkout URL for the order total, and the Stripe confirm route
348	 * provisions the server on successful payment.
349	 */
350	export async function payAndDeploy(
351	  prev: any,
352	  formData: FormData,
353	): Promise<{ error?: string; checkoutUrl?: string }> {
354	  const user = await requireUser();
355	  // Same per-user server cap as orderServer (this is the card-pay deploy path).
356	  const limitErr = await serverLimitError(user.id);
357	  if (limitErr) return { error: limitErr };
358	  const intent = intentFromFormData(formData);
359	
360	  let quote;
361	  try {
362	    quote = await orderQuote(intent);
363	  } catch (e) {
364	    if (e instanceof OrderError) return { error: e.message };
365	    throw e;
366	  }
367	
368	  const isAdmin = user.role === "ADMIN";
369	  const payFromWallet = (intent.free && isAdmin) || user.balanceCents >= quote.chargeCents;
370	
371	  if (payFromWallet) {
372	    let serverId: string;
373	    try {
374	      serverId = await placeOrder(user, intent);
375	    } catch (e) {
376	      if (e instanceof OrderError) return { error: e.message };
377	      throw e;
378	    }
379	    redirect(`/dashboard/servers/${serverId}`);
380	  }
381	
382	  // Pay for the server directly by card; provisioned on payment success.
383	  const url = await createOrderCheckout(user, quote.chargeCents, intent);
384	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
385	  return { checkoutUrl: url };
386	}
387	
388	// ---------- Server lifecycle ----------
389	
390	async function ownedServer(serverId: string) {
391	  const user = await requireUser();
392	  const server = await db.server.findUnique({ where: { id: serverId } });
393	  if (!server) throw new Error("Not found");
394	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
395	  return { user, server };
396	}
397	
398	export async function serverAction(serverId: string, action: string) {
399	  const { user, server } = await ownedServer(serverId);
400	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
401	    start: "START",
402	    stop: "STOP",
403	    reboot: "REBOOT",
404	    reinstall: "REINSTALL",
405	    delete: "DELETE",
406	  };
407	  const type = allowed[action];
408	  if (!type) throw new Error("Invalid action");
409	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
410	    throw new Error("Server is suspended");
411	  }
412	
413	  const pending = await db.job.count({
414	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
415	  });
416	  if (pending > 0) return; // debounce: one job at a time per server
417	
418	  if (type === "DELETE") {
