514	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
515	  const { user, server } = await ownedServer(serverId);
516	  if (server.isFree || !server.expiresAt) return;
517	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
518	  if (!plan) return;
519	  const term = vpsTerm(server.termMonths);
520	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
521	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
522	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
523	    where: { serverId }, select: { id: true },
524	  }));
525	  const renewCents =
526	    vpsTermPriceCents(plan.priceCents, term.months) +
527	    (hasDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0);
528	  const owner = await db.user.findUnique({ where: { id: server.userId } });
529	  if (!owner || owner.balanceCents < renewCents) {
530	    return { error: "Insufficient balance — top up your wallet first." };
531	  }
532	
533	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
534	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
535	  // can't both read E, both debit, and both write E+term (double-charge, one
536	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
537	  const E = server.expiresAt;
538	  const base = new Date(Math.max(E.getTime(), Date.now()));
539	  const newExpiry = addMonths(base, term.months);
540	  try {
541	    await db.$transaction(async (tx) => {
542	      // Compare-and-swap the expiry first; if it no longer equals E another
543	      // renewal already advanced it — bail without charging (tx rolls back).
544	      const adv = await tx.server.updateMany({
545	        where: { id: serverId, expiresAt: E },
546	        data: { expiresAt: newExpiry, suspendedNote: null },
547	      });
548	      if (adv.count === 0) throw new AlreadyRenewedError();
549	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
550	      await debitWallet(tx, server.userId, renewCents);
551	      await tx.walletTransaction.create({
552	        data: {
553	          userId: server.userId,
554	          amountCents: -renewCents,
555	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
556	        },
557	      });
558	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
559	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
560	      await tx.invoice.create({
561	        data: invoiceCreateData({
562	          userId: server.userId,
563	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
564	          status: "PAID",
565	          period: { start: E, end: newExpiry },
566	          lineItems: [
567	            { description: `${plan.name} VPS (${server.hostname}) — ${term.label}`, qty: 1, unitCents: renewCents, amountCents: renewCents },
568	          ],
569	        }),
570	      });
571	    });
572	  } catch (e) {
573	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
574	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
575	    throw e;
576	  }
577	  await audit(user.id, "server.renew_now", serverId);
578	
579	  // Unpaid-suspended server springs back to life once paid
580	  if (server.status === "SUSPENDED") {
581	    const pending = await db.job.count({
582	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
583	    });
584	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
585	  }
586	  revalidatePath(`/dashboard/servers/${serverId}`);
587	}
