16	 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
17	 *      success `totpEnabled` flips true and backup codes are generated.
18	 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
19	 *      the account password.
20	 *
21	 * Backup codes are one-time; only their sha256 hashes are stored.
22	 */
23	
24	function hashCode(code: string): string {
25	  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
26	}
27	
28	/** Generate N human-friendly one-time backup codes (plaintext, for display). */
29	function makeBackupCodes(n = 10): string[] {
30	  return Array.from({ length: n }, () => {
31	    const raw = randomBytes(5).toString("hex"); // 10 hex chars
32	    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
33	  });
34	}
35	
36	/**
37	 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
38	 * valid one-time backup code (which is then removed). Intended to be called by
39	 * the login flow once the password check succeeds.
40	 */
41	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
42	  const user = await db.user.findUnique({ where: { id: userId } });
43	  if (!user || !user.totpEnabled || !user.totpSecret) return false;
44	
45	  if (verifyTOTP(user.totpSecret, code)) return true;
46	
47	  // Fall back to consuming a backup code.
48	  const submitted = hashCode(code);
49	  const idx = user.backupCodes.indexOf(submitted);
50	  if (idx === -1) return false;
51	  const remaining = user.backupCodes.filter((_, i) => i !== idx);
52	  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
53	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
54	  return true;
55	}
56	
57	/**
58	 * Step 1: create (but do not yet activate) a TOTP secret.
59	 *
60	 * Return shape keeps `secret`/`otpauthUrl` present (empty on refusal) so the
61	 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
62	 * optional `error` is populated when enrolment is refused.
63	 */
64	export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
65	  const user = await requireUser();
66	
67	  // Block enrolment while impersonating: the real acting account must be the
68	  // same account being enrolled, so an admin can't seed a customer's 2FA.
69	  const real = await realUser();
70	  if (!real || real.id !== user.id) {
71	    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
72	  }
73	
74	  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
75	  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
76	  if (user.totpEnabled === true) {
77	    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
78	  }
79	
80	  const secret = generateSecret();
81	  await db.user.update({
82	    where: { id: user.id },
83	    data: { totpSecret: secret, totpEnabled: false },
84	  });
85	  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
86	}
87	
88	/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
89	export async function confirmTotpEnrollment(
90	  prev: unknown,
91	  formData: FormData,
92	): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
93	  const user = await requireUser();
94	  const code = String(formData.get("code") ?? "");
95	  if (!user.totpSecret) return { error: "Start enrolment first." };
96	  if (!verifyTOTP(user.totpSecret, code)) return { error: "That code is incorrect. Try again." };
97	
98	  const backupCodes = makeBackupCodes();
99	  await db.user.update({
100	    where: { id: user.id },
101	    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
102	  });
103	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
104	  revalidatePath("/dashboard/settings");
105	  return { ok: true, backupCodes };
106	}
107	
108	/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
109	export async function regenerateBackupCodes(
110	  prev: unknown,
111	  formData: FormData,
112	): Promise<{ error?: string; backupCodes?: string[] }> {
113	  const user = await requireUser();
114	  const code = String(formData.get("code") ?? "");
115	  if (!user.totpEnabled || !user.totpSecret) return { error: "2FA is not enabled." };
116	  if (!verifyTOTP(user.totpSecret, code)) return { error: "That code is incorrect." };
117	  const backupCodes = makeBackupCodes();
118	  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
119	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
120	  return { backupCodes };
121	}
122	
123	/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
124	export async function disableTotp(
125	  prev: unknown,
126	  formData: FormData,
127	): Promise<{ error?: string; ok?: boolean }> {
128	  const user = await requireUser();
129	  const proof = String(formData.get("proof") ?? "");
130	  if (!user.totpEnabled) return { error: "2FA is not enabled." };
131	
132	  const codeValid =
133	    (user.totpSecret ? verifyTOTP(user.totpSecret, proof) : false) ||
134	    (await verifyTotpForUser(user.id, proof));
135	  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
136	  if (!codeValid && !passwordValid) {
137	    return { error: "Enter a valid authenticator code, backup code, or your password." };
138	  }
139	
140	  await db.user.update({
141	    where: { id: user.id },
142	    data: { totpEnabled: false, totpSecret: null, backupCodes: [] },
143	  });
144	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
145	  revalidatePath("/dashboard/settings");
146	  return { ok: true };
147	}
