18	/**
19	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
20	 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
21	 */
22	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
23	  switch (coupon.kind) {
24	    case "PERCENT":
25	      return Math.round((baseCents * coupon.value) / 100);
26	    case "FIXED_CENTS":
27	    case "CREDIT_CENTS":
28	      return coupon.value;
29	    default:
30	      return 0;
31	  }
32	}
