34	/**
35	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
36	 * return the bonus that would be credited. Read-only: it never mutates state,
37	 * so it is safe to call both for the live preview (CouponField) and again inside
38	 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
39	 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
40	 */
41	export async function applyCouponToTopup(
42	  code: string,
43	  baseCents: number
44	): Promise<CouponApplyResult> {
45	  const user = await requireUser();
46	  // Global kill-switch: when coupons are disabled no code may be redeemed.
47	  // Checked here so both the live preview and the real `topUp` apply are covered.
48	  if (!(await getSettingBool("coupons_enabled", true))) {
49	    return { ok: false, error: "Promo codes are currently disabled." };
50	  }
51	  const normalized = String(code ?? "").trim().toUpperCase();
52	  if (!normalized) return { ok: false, error: "Enter a promo code." };
53	
54	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
55	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
56	  if (coupon.scope === "ORDER") {
57	    return { ok: false, error: "This code only applies to server orders." };
58	  }
59	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
60	    return { ok: false, error: "This code has expired." };
61	  }
62	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
63	    return { ok: false, error: "This code has reached its redemption limit." };
64	  }
65	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
66	    return {
67	      ok: false,
68	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
69	    };
70	  }
71	
72	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
73	  const already = await db.couponRedemption.findUnique({
74	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
75	  });
76	  if (already) return { ok: false, error: "You’ve already used this code." };
77	
78	  if (coupon.firstTimeOnly) {
79	    // "First-time" = the user has never received a positive wallet credit before.
80	    const priorCredits = await db.walletTransaction.count({
81	      where: { userId: user.id, amountCents: { gt: 0 } },
82	    });
83	    if (priorCredits > 0) {
84	      return { ok: false, error: "This code is for first-time customers only." };
85	    }
86	  }
87	
88	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
89	  return {
90	    ok: true,
91	    couponId: coupon.id,
92	    code: coupon.code,
93	    bonusCents,
94	    label: describeCoupon(coupon),
95	  };
96	}
